content.text:
    maskPaymentMethod(method: any) {
      const last4 = method?.last_four_number || method?.last4 || method?.creditCard?.last4 || method?.card?.last4
      return last4 ? `•••• ${last4}` : (method?.reference || method?.id || 'Sin terminación')
    },
    openRechargeDialog() {
      this.rechargeForm = {
        reference: '',
        amount: 1,
        comment: '',
        typePayment: 'MANUAL',
        paymentMethod: null,
      }
      this.rechargeLoading = false
      this.rechargeSuccess = false
      this.rechargeDialog = true
    },
    async submitRecharge() {
      if (!this.isValidRechargeAmount) {
        this.$q.notify({
          type: 'negative',
          message: 'El monto debe estar entre USD 1.00 y USD 1,000.00',
        })
        return
      }
      const recharge = {
        token : 'CASH',
        amount: this.rechargeForm.amount,
        source: 'WEB',
        entity: 'KLUBO_CASH',
        data: {
          transaction: {
            mode: 'MANUAL',
            reference: this.rechargeForm.reference,
            method: this.rechargeForm.paymentMethod,
          },
          operator: {
            id: this.user.id,
            name: this.user.name,
          }
        }
      }
      this.rechargeLoading = true
      try {
        await rechargeKluboCashBalanceClub(recharge);
        await getUserWallet(this.user.id);
        await getUserWalletTransactions(this.user.id, this.transactionsFilter);

        this.rechargeSuccess = true
        window.setTimeout(() => {
          this.rechargeSuccess = false
        }, 2500)
      } finally {
        this.rechargeLoading = false
      }
    },
    async changeTransactionsPage(page: number) {
      this.setPage(page)
      this.transactionsFilter.page = this.currentPage
      this.transactionsFilter.limit = this.itemsPerPage
      this.transactionsLoading = true
      await getUserWalletTransactions(this.userId, this.transactionsFilter)
      this.transactionsLoading = false
    },
  },
  beforeMount() {
    this.resetAll()
  },
  async mounted() {
    this.pageLoaded = false
    this.transactionsFilter.page = this.currentPage
    this.transactionsFilter.limit = this.itemsPerPage

    const userId = this.$route.params.id as string;
    await getUserById(userId);
    await getUserWallet(userId);
    await getUserWalletTransactions(userId, this.transactionsFilter);
    this.pageLoaded = true
  },
})
</script>

